@page "/apply"
@using sv_f485e38fd5cf414ba15727989876f169.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <!-- Step Indicator Bar -->
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < CurrentStep)
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (i < StepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!IsSubmitted)
    {
        <!-- Validation Errors -->
        @if (ValidationErrors.Count > 0)
        {
            <div class="validation-errors">
                @foreach (var error in ValidationErrors)
                {
                    <p class="error">@error</p>
                }
            </div>
        }

        <!-- Step 1: Personal Info -->
        @if (CurrentStep == 0)
        {
            <div class="step-content">
                <h2>Personal Information</h2>
                <div class="form-group">
                    <label for="fullName">Full Name *</label>
                    <input id="fullName" type="text" @bind="FullName" placeholder="Enter your full name" />
                </div>
                <div class="form-group">
                    <label for="email">Email *</label>
                    <input id="email" type="email" @bind="Email" placeholder="Enter your email" />
                </div>
                <div class="form-group">
                    <label for="phone">Phone *</label>
                    <input id="phone" type="tel" @bind="Phone" placeholder="Enter your phone number" />
                </div>
                <div class="form-group">
                    <label for="address">Address *</label>
                    <input id="address" type="text" @bind="Address" placeholder="Enter your address" />
                </div>
                <div class="form-actions">
                    <button class="btn-next" @onclick="NextStep" disabled="@IsProcessing">
                        @if (IsProcessing) { <span>Validating...</span> } else { <span>Next</span> }
                    </button>
                </div>
            </div>
        }

        <!-- Step 2: Work History -->
        @if (CurrentStep == 1)
        {
            <div class="step-content">
                <h2>Work History</h2>
                @for (int i = 0; i < WorkEntries.Count; i++)
                {
                    var index = i;
                    <div class="work-entry-card">
                        <div class="work-entry-header">
                            <h3>Position @(index + 1)</h3>
                            @if (WorkEntries.Count > 1)
                            {
                                <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="form-group">
                            <label>Company Name *</label>
                            <input type="text" @bind="WorkEntries[index].Company" placeholder="Company name" />
                        </div>
                        <div class="form-group">
                            <label>Job Title *</label>
                            <input type="text" @bind="WorkEntries[index].Title" placeholder="Job title" />
                        </div>
                        <div class="form-row">
                            <div class="form-group">
                                <label>Start Date *</label>
                                <input type="date" @bind="WorkEntries[index].StartDate" />
                            </div>
                            <div class="form-group">
                                <label>End Date</label>
                                <input type="date" @bind="WorkEntries[index].EndDate" disabled="@WorkEntries[index].IsCurrent" />
                            </div>
                        </div>
                        <div class="form-group checkbox-group">
                            <input type="checkbox" id="current-@index" @bind="WorkEntries[index].IsCurrent" />
                            <label for="current-@index">I currently work here</label>
                        </div>
                        <div class="form-group">
                            <label>Description</label>
                            <textarea @bind="WorkEntries[index].Description" placeholder="Describe your role and responsibilities"></textarea>
                        </div>
                    </div>
                }
                <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
                <div class="form-actions">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-next" @onclick="NextStep">Next</button>
                </div>
            </div>
        }

        <!-- Step 3: References -->
        @if (CurrentStep == 2)
        {
            <div class="step-content">
                <h2>References</h2>
                @for (int i = 0; i < References.Count; i++)
                {
                    var index = i;
                    <div class="reference-card">
                        <div class="work-entry-header">
                            <h3>Reference @(index + 1)</h3>
                            @if (References.Count > 2)
                            {
                                <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="form-group">
                            <label>Name *</label>
                            <input type="text" @bind="References[index].Name" placeholder="Reference name" />
                        </div>
                        <div class="form-group">
                            <label>Relationship *</label>
                            <input type="text" @bind="References[index].Relationship" placeholder="e.g., Former Manager" />
                        </div>
                        <div class="form-group">
                            <label>Email *</label>
                            <input type="email" @bind="References[index].Email" placeholder="Reference email" />
                        </div>
                        <div class="form-group">
                            <label>Phone *</label>
                            <input type="tel" @bind="References[index].Phone" placeholder="Reference phone" />
                        </div>
                    </div>
                }
                @if (References.Count < 3)
                {
                    <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
                }
                <div class="form-actions">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-next" @onclick="NextStep">Next</button>
                </div>
            </div>
        }

        <!-- Step 4: Cover Letter -->
        @if (CurrentStep == 3)
        {
            <div class="step-content">
                <h2>Cover Letter</h2>
                <div class="form-group">
                    <label for="coverLetter">Write your cover letter</label>
                    <textarea id="coverLetter" class="cover-letter-textarea" @bind="CoverLetter" @bind:event="oninput" maxlength="2000" placeholder="Tell us why you're a great fit for this position..."></textarea>
                    <div class="character-count">@CoverLetter.Length / 2000 characters</div>
                </div>
                <div class="form-actions">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-next" @onclick="NextStep">Next</button>
                </div>
            </div>
        }

        <!-- Step 5: Review & Submit -->
        @if (CurrentStep == 4)
        {
            <div class="step-content">
                <h2>Review & Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl class="review-details">
                        <dt>Full Name</dt><dd>@FullName</dd>
                        <dt>Email</dt><dd>@Email</dd>
                        <dt>Phone</dt><dd>@Phone</dd>
                        <dt>Address</dt><dd>@Address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in WorkEntries)
                    {
                        <div class="review-work-entry">
                            <p><strong>@entry.Title</strong> at @entry.Company</p>
                            <p class="review-dates">@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</p>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="review-description">@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var reference in References)
                    {
                        <div class="review-reference">
                            <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                            <p>@reference.Email | @reference.Phone</p>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <p class="review-cover-letter">@CoverLetter</p>
                </div>

                <div class="form-actions">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@IsProcessing">
                        @if (IsProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                    </button>
                </div>
            </div>
        }
    }
    else
    {
        <!-- Submission Confirmation -->
        <div class="confirmation">
            <div class="confirmation-icon">✓</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been submitted successfully.</p>
            <p class="application-id">Application ID: <strong>@ApplicationId</strong></p>
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private bool IsProcessing { get; set; }
    private bool IsSubmitted { get; set; }
    private int ApplicationId { get; set; }
    private List<string> ValidationErrors { get; set; } = new();

    // Step 1: Personal Info
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2: Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string CoverLetter { get; set; } = "";

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex < CurrentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex < CurrentStep)
        {
            CurrentStep = stepIndex;
            ValidationErrors.Clear();
        }
    }

    private void GoToStep(int stepIndex)
    {
        CurrentStep = stepIndex;
        ValidationErrors.Clear();
    }

    private async Task NextStep()
    {
        ValidationErrors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (CurrentStep == 0)
        {
            IsProcessing = true;
            var isEmailValid = await ApplicationService.ValidateEmailAsync(Email);
            IsProcessing = false;

            if (!isEmailValid)
            {
                ValidationErrors.Add("The email address is not valid.");
                return;
            }
        }

        CurrentStep++;
    }

    private void PreviousStep()
    {
        if (CurrentStep > 0)
        {
            CurrentStep--;
            ValidationErrors.Clear();
        }
    }

    private bool ValidateCurrentStep()
    {
        return CurrentStep switch
        {
            0 => ValidatePersonalInfo(),
            1 => ValidateWorkHistory(),
            2 => ValidateReferences(),
            3 => ValidateCoverLetter(),
            _ => true
        };
    }

    private bool ValidatePersonalInfo()
    {
        if (string.IsNullOrWhiteSpace(FullName))
            ValidationErrors.Add("Full name is required.");
        if (string.IsNullOrWhiteSpace(Email))
            ValidationErrors.Add("Email is required.");
        if (string.IsNullOrWhiteSpace(Phone))
            ValidationErrors.Add("Phone is required.");
        if (string.IsNullOrWhiteSpace(Address))
            ValidationErrors.Add("Address is required.");
        return ValidationErrors.Count == 0;
    }

    private bool ValidateWorkHistory()
    {
        for (int i = 0; i < WorkEntries.Count; i++)
        {
            var entry = WorkEntries[i];
            if (string.IsNullOrWhiteSpace(entry.Company))
                ValidationErrors.Add($"Position {i + 1}: Company name is required.");
            if (string.IsNullOrWhiteSpace(entry.Title))
                ValidationErrors.Add($"Position {i + 1}: Job title is required.");
            if (entry.StartDate == default)
                ValidationErrors.Add($"Position {i + 1}: Start date is required.");
        }
        return ValidationErrors.Count == 0;
    }

