@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private bool IsProcessing { get; set; }
    private bool IsSubmitted { get; set; }
    private int ApplicationId { get; set; }
    private List<string> ValidationErrors { get; set; } = new();

    // Step 1: Personal Info
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2: Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string CoverLetter { get; set; } = "";

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex < CurrentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex < CurrentStep)
        {
            CurrentStep = stepIndex;
            ValidationErrors.Clear();
        }
    }

    private void GoToStep(int stepIndex)
    {
        CurrentStep = stepIndex;
        ValidationErrors.Clear();
    }

    private async Task NextStep()
    {
        ValidationErrors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (CurrentStep == 0)
        {
            IsProcessing = true;
            var isEmailValid = await ApplicationService.ValidateEmailAsync(Email);
            IsProcessing = false;

            if (!isEmailValid)
            {
                ValidationErrors.Add("The email address is not valid.");
                return;
            }
        }

        CurrentStep++;
    }

    private void PreviousStep()
    {
        if (CurrentStep > 0)
        {
            CurrentStep--;
            ValidationErrors.Clear();
        }
    }

    private bool ValidateCurrentStep()
    {
        return CurrentStep switch
        {
            0 => ValidatePersonalInfo(),
            1 => ValidateWorkHistory(),
            2 => ValidateReferences(),
            3 => ValidateCoverLetter(),
            _ => true
        };
    }

    private bool ValidatePersonalInfo()
    {
        if (string.IsNullOrWhiteSpace(FullName))
            ValidationErrors.Add("Full name is required.");
        if (string.IsNullOrWhiteSpace(Email))
            ValidationErrors.Add("Email is required.");
        if (string.IsNullOrWhiteSpace(Phone))
            ValidationErrors.Add("Phone is required.");
        if (string.IsNullOrWhiteSpace(Address))
            ValidationErrors.Add("Address is required.");
        return ValidationErrors.Count == 0;
    }

    private bool ValidateWorkHistory()
    {
        for (int i = 0; i < WorkEntries.Count; i++)
        {
            var entry = WorkEntries[i];
            if (string.IsNullOrWhiteSpace(entry.Company))
                ValidationErrors.Add($"Position {i + 1}: Company name is required.");
            if (string.IsNullOrWhiteSpace(entry.Title))
                ValidationErrors.Add($"Position {i + 1}: Job title is required.");
            if (entry.StartDate == default)
                ValidationErrors.Add($"Position {i + 1}: Start date is required.");
        }
        return ValidationErrors.Count == 0;
    }

    private bool ValidateReferences()
    {
        for (int i = 0; i < References.Count; i++)
        {
            var r = References[i];
            if (string.IsNullOrWhiteSpace(r.Name))
                ValidationErrors.Add($"Reference {i + 1}: Name is required.");
            if (string.IsNullOrWhiteSpace(r.Relationship))
                ValidationErrors.Add($"Reference {i + 1}: Relationship is required.");
            if (string.IsNullOrWhiteSpace(r.Email))
                ValidationErrors.Add($"Reference {i + 1}: Email is required.");
            if (string.IsNullOrWhiteSpace(r.Phone))
                ValidationErrors.Add($"Reference {i + 1}: Phone is required.");
        }
        return ValidationErrors.Count == 0;
    }

    private bool ValidateCoverLetter()
    {
        if (string.IsNullOrWhiteSpace(CoverLetter))
            ValidationErrors.Add("Cover letter is required.");
        return ValidationErrors.Count == 0;
    }

    private void AddWorkEntry()
    {
        WorkEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        IsProcessing = true;

        var personalInfo = new PersonalInfo(FullName, Email, Phone, Address);
        var workHistory = new WorkHistory(WorkEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)
        ).ToList());
        var references = References.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)
        ).ToList();

        var application = new JobApplication(personalInfo, workHistory, references, CoverLetter);
        ApplicationId = await ApplicationService.SubmitApplicationAsync(application);

        IsProcessing = false;
        IsSubmitted = true;
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

