                            <p class="review-dates">@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</p>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
